<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_core_admin_overview() { if ( ! current_user_can( 'sd_view_reports' ) ) { wp_die( esc_html__( 'You are not allowed to view this page.', 'social-discovery-core' ) ); } global $wpdb; $t = sd_core_table_names(); $pending = absint( $wpdb->get_var( "SELECT COUNT(*) FROM {$t['reports']} WHERE status='pending'" ) ); $review = absint( $wpdb->get_var( "SELECT COUNT(*) FROM {$t['reports']} WHERE status='under_review'" ) ); $restricted = absint( $wpdb->get_var( "SELECT COUNT(DISTINCT user_id) FROM {$t['restrictions']} WHERE active=1" ) ); $member_count = count_users(); ?><div class="wrap"><h1><?php esc_html_e( 'Social Discovery Overview', 'social-discovery-core' ); ?></h1><div class="sd-admin-cards"><div><strong><?php echo esc_html( number_format_i18n( $member_count['total_users'] ) ); ?></strong><span><?php esc_html_e( 'Members', 'social-discovery-core' ); ?></span></div><div><strong><?php echo esc_html( $pending ); ?></strong><span><?php esc_html_e( 'Pending reports', 'social-discovery-core' ); ?></span></div><div><strong><?php echo esc_html( $review ); ?></strong><span><?php esc_html_e( 'Under review', 'social-discovery-core' ); ?></span></div><div><strong><?php echo esc_html( $restricted ); ?></strong><span><?php esc_html_e( 'Restricted accounts', 'social-discovery-core' ); ?></span></div></div><p><a class="button button-primary" href="<?php echo esc_url( admin_url( 'admin.php?page=sd-moderation-queue' ) ); ?>"><?php esc_html_e( 'Open moderation queue', 'social-discovery-core' ); ?></a></p></div><?php }
